function remoteEvent(event, settings) {
  const commands = [
    "arrow_left_click",
    "arrow_right_click",
    "brightness_up_click",
    "brightness_down_click",
    "toggle",
    "brightness_up_hold",
    "brightness_down_hold",
  ];
  if (!commands.includes(event?.message) || typeof event.topic !== "string" || !event.topic)
    return null;
  if (event.message === "arrow_left_click" || event.message === "arrow_right_click")
    return { command: event.message, arrow: true };
  if (typeof settings.deviceName !== "string" || !settings.deviceName.trim())
    throw Error("Set the exact Spotify Connect device name.");
  if (
    event.message === "brightness_up_hold" &&
    !/^spotify:track:[A-Za-z0-9]{22}$/.test(settings.trackUri ?? "")
  ) {
    throw Error("Set a Spotify track URI for the volume, queue and skip shortcut.");
  }
  if (
    event.message === "brightness_down_hold" &&
    (typeof settings.playlistName !== "string" || !settings.playlistName.trim())
  ) {
    throw Error("Set the exact playlist name for the playlist shortcut.");
  }
  return { command: event.message, arrow: false, ...settings };
}

const settings = {
  deviceName: "",
  trackUri: "",
  playlistName: "",
};
const job = remoteEvent($input.first().json, settings);
return job ? [{ json: job, pairedItem: { item: 0 } }] : [];

const operation = $input.first().json.command === "arrow_left_click" ? "previous" : "next";
return [
  {
    json: { method: "POST", url: "https://api.spotify.com/v1/me/player/" + operation, body: null },
    pairedItem: { item: 0 },
  },
];

function readSpotifyPlayback(response) {
  if (response.statusCode === 204) return null;
  if (response.statusCode !== 200 || typeof response.data !== "string")
    throw Error("Spotify did not return playback state.");
  let playback;
  try {
    playback = JSON.parse(response.data);
  } catch {
    throw Error("Spotify returned invalid playback state.");
  }
  if (!playback || typeof playback !== "object" || typeof playback.is_playing !== "boolean")
    throw Error("Spotify returned invalid playback state.");
  return playback;
}
function remoteContext(job, playback, devices) {
  if (devices.statusCode !== 200 || !Array.isArray(devices.body?.devices))
    throw Error("Spotify did not return available devices.");
  const matches = devices.body.devices.filter((device) => device?.name === job.deviceName);
  if (matches.length !== 1)
    throw Error("The configured Spotify device is unavailable or its name is ambiguous.");
  const device = matches[0];
  if (
    typeof device.id !== "string" ||
    !device.id ||
    device.id.length > 250 ||
    device.is_restricted !== false
  ) {
    throw Error("The configured Spotify device cannot be controlled.");
  }
  const selected = playback?.device?.id === device.id;
  const isPlaying = selected && playback.is_playing;
  const volume =
    selected && Number.isInteger(playback.device.volume_percent)
      ? playback.device.volume_percent
      : device.volume_percent;
  const canSetVolume =
    device.supports_volume !== false && (!selected || playback.device.supports_volume !== false);
  return { ...job, deviceId: device.id, needsTransfer: !selected, isPlaying, volume, canSetVolume };
}

const state = readSpotifyPlayback($("Read Spotify playback state").first().json);
return [
  {
    json: remoteContext(
      $("Set the Spotify device and shortcuts").first().json,
      state,
      $input.first().json,
    ),
    pairedItem: { item: 0 },
  },
];

