function remoteRequests(job, playlist = null) {
  const write = (method, operation, query = {}, body = null) => ({
    method,
    url:
      "https://api.spotify.com/v1/me/player/" +
      operation +
      "?" +
      Object.entries({ device_id: job.deviceId, ...query })
        .map(([name, value]) => name + "=" + encodeURIComponent(value))
        .join("&"),
    body,
  });
  const volume = (value) => write("PUT", "volume", { volume_percent: value });
  const step = (amount) => {
    if (!job.canSetVolume || !Number.isInteger(job.volume) || job.volume < 0 || job.volume > 100)
      throw Error("The target device did not return a usable volume.");
    return volume(amount > 0 ? Math.min(job.volume + 5, 100) : Math.max(job.volume - 5, 20));
  };
  let requests;
  switch (job.command) {
    case "brightness_up_click":
      requests = [step(5)];
      break;
    case "brightness_down_click":
      requests = [step(-5)];
      break;
    case "toggle":
      requests = [write("PUT", job.isPlaying ? "pause" : "play")];
      break;
    case "brightness_up_hold":
      if (!job.canSetVolume) throw Error("The target device does not support setting volume.");
      requests = [volume(80), write("POST", "queue", { uri: job.trackUri }), write("POST", "next")];
      break;
    case "brightness_down_hold":
      if (!playlist) throw Error("The playlist shortcut did not resolve a playlist.");
      requests = [write("PUT", "play", {}, { context_uri: playlist })];
      break;
    default:
      throw Error("Unsupported remote command.");
  }
  if (job.needsTransfer)
    requests.unshift({
      method: "PUT",
      url: "https://api.spotify.com/v1/me/player",
      body: { device_ids: [job.deviceId], play: true },
    });
  return requests;
}

return remoteRequests($input.first().json).map((json) => ({ json, pairedItem: { item: 0 } }));

function playlistContext(pages, playlistName) {
  if (!pages.length || pages.at(-1).body?.next !== null)
    throw Error("Spotify did not return a complete playlist list.");
  const matches = [];
  for (const { statusCode, body } of pages) {
    if (statusCode !== 200 || !Array.isArray(body?.items))
      throw Error("Spotify returned an invalid playlist page.");
    matches.push(...body.items.filter((item) => item?.name === playlistName));
  }
  if (
    matches.length !== 1 ||
    typeof matches[0].id !== "string" ||
    !/^[A-Za-z0-9]{22}$/.test(matches[0].id)
  ) {
    throw Error("The configured Spotify playlist is unavailable or its name is ambiguous.");
  }
  return "spotify:playlist:" + matches[0].id;
}
