const job = $("Match the configured device").first().json;
return remoteRequests(
  job,
  playlistContext(
    $input.all().map((item) => item.json),
    job.playlistName,
  ),
).map((json) => ({ json, pairedItem: { item: 0 } }));

if ($input.first().json.statusCode !== 204)
  throw Error("Spotify did not confirm the command. Check playback before repeating it.");
return [{ json: { accepted: true }, pairedItem: { item: 0 } }];
